<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\KeyConfig;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\KeyPair;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Exception\NoActiveKeyException;

final class TokenSecurityDomainUnitTest extends TestCase
{
    // --- KeyConfig ---

    public function test_key_config_defaults(): void
    {
        $config = new KeyConfig();

        $this->assertSame(3, $config->futures);
        $this->assertSame('P7D', $config->ttl->format('P%dD'));
    }

    // --- KeyPair ---

    public function test_key_pair_stores_all_fields(): void
    {
        $kp = new KeyPair(
            kid: 'key-2026-01',
            alg: 'RS256',
            keyUse: 'sig',
            privateKey: '-----BEGIN PRIVATE KEY-----',
            publicKey: '-----BEGIN PUBLIC KEY-----',
        );

        $this->assertSame('key-2026-01', $kp->kid);
        $this->assertSame('RS256', $kp->alg);
        $this->assertSame('sig', $kp->keyUse);
        $this->assertSame('-----BEGIN PRIVATE KEY-----', $kp->privateKey);
        $this->assertSame('-----BEGIN PUBLIC KEY-----', $kp->publicKey);
    }

    // --- NoActiveKeyException ---

    public function test_no_active_key_exception_is_runtime_exception(): void
    {
        $ex = new NoActiveKeyException('No active key found');
        $this->assertInstanceOf(\RuntimeException::class, $ex);
        $this->assertSame('No active key found', $ex->getMessage());
    }

    public function test_no_active_key_exception_can_be_thrown_and_caught(): void
    {
        $this->expectException(NoActiveKeyException::class);
        throw new NoActiveKeyException('No key available');
    }
}
